/**
 * /pages/Login.jsx
 * ---------------------------------------------------------------------------
 * Trang đăng nhập (layout blank — không dùng MainLayout).
 * Demo gọi api.authApi.login() và lưu token vào state + localStorage.
 */

import React, { useState } from 'react'
import { Card, Form, Input, Button, Checkbox, Typography, Alert, Space } from 'antd'
import { UserOutlined, LockOutlined } from '@ant-design/icons'

import api from '@/model/api'
import { useAppDispatch, mutations } from '@/store'
import { useRouter, useRoute } from '@/router'
import { useI18n } from '@/lang'
import LanguageSwitcher from '@/components/LanguageSwitcher'

const { Title, Text } = Typography
const TOKEN_KEY = import.meta.env.VITE_TOKEN_KEY || 'reactjs_sample_token'

const Login = () => {
  const router = useRouter()
  const route = useRoute()
  const dispatch = useAppDispatch()
  const { t } = useI18n()
  const [loading, setLoading] = useState(false)

  const onFinish = async (values) => {
    setLoading(true)
    try {
      // ---- Demo: giả lập đăng nhập thành công ----------------------------
      // Thực tế: const res = await api.authApi.login(values)
      await new Promise((r) => setTimeout(r, 500))
      const res = {
        token: 'demo-token-' + Date.now(),
        user: { name: values.username, role: 'admin' },
      }

      dispatch(mutations.setToken(res.token))
      dispatch(mutations.setUserInfo(res.user))
      localStorage.setItem(TOKEN_KEY, res.token)

      router.replace(route.query.redirect || '/')
    } catch (e) {
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="login-page">
      <Card className="login-card">
        <div className="login-lang">
          <LanguageSwitcher showLabel={false} />
        </div>

        <Space direction="vertical" size={4} className="login-heading">
          <Title level={3} className="login-title">
            {t('Đăng nhập')}
          </Title>
          <Text type="secondary">ReactJS Sample</Text>
        </Space>

        <Alert
          type="info"
          showIcon
          className="login-alert"
          message={t('Nhập bất kỳ tài khoản / mật khẩu để vào (demo)')}
        />

        <Form layout="vertical" onFinish={onFinish} initialValues={{ remember: true }}>
          <Form.Item
            name="username"
            label={t('Tài khoản')}
            rules={[{ required: true, message: t('Vui lòng nhập tài khoản') }]}
          >
            <Input prefix={<UserOutlined />} placeholder="admin" size="large" />
          </Form.Item>

          <Form.Item
            name="password"
            label={t('Mật khẩu')}
            rules={[{ required: true, message: t('Vui lòng nhập mật khẩu') }]}
          >
            <Input.Password prefix={<LockOutlined />} placeholder="123456" size="large" />
          </Form.Item>

          <Form.Item name="remember" valuePropName="checked" className="login-remember">
            <Checkbox>{t('Ghi nhớ đăng nhập')}</Checkbox>
          </Form.Item>

          <Button type="primary" htmlType="submit" block size="large" loading={loading}>
            {t('Đăng nhập')}
          </Button>
        </Form>
      </Card>
    </div>
  )
}

export default Login
